/**
 * @vitest-environment node
 *
 * KEPT RED TEST — issue #1897, proof 1 of 2.
 *
 * ## Context
 *
 * Issue #1897: the blanket *.g.cs exclusion pattern hid ALL .g.cs files,
 * even those that are hand-maintained and contain real duplication. Only
 * ResponseKeys.g.cs (auto-generated by PublyApp.Scripts) should be excluded.
 *
 * The fix: GENERATED_FILE_PATHS is an explicit Set containing only
 * ResponseKeys.g.cs. Arbitrary .g.cs files are no longer excluded.
 *
 * ## What the proof asserts (kept-red direction)
 *
 * The proof asserts the BUGGY outcome: an arbitrary .g.cs file IS excluded
 * by isSpecFile() — the blanket pattern is still in effect.
 *
 * - CORRECTED code: isSpecFile() returns false (not in GENERATED_FILE_PATHS).
 *   `expect(result).toBe(true)` FAILS — the kept-red state.
 * - BUG re-introduced (blanket pattern restored): isSpecFile() returns true
 *   → the assertion PASSES → replay red.
 *
 * ## Replay
 *   cd packages/scripts-ts && pnpm exec vitest run --config vitest.preuves.config.ts \
 *     tests/proofs/1897/red-1897-blanket-gcs-exclusion.test.ts
 *
 * Expected: FAIL — on corrected code the arbitrary .g.cs is NOT excluded,
 * so `expect(result).toBe(true)` fails.
 */
import assert from 'node:assert/strict';

import { test } from 'vitest';

import { isSpecFile } from '../../../src/check-jscpd.ts';

test('RED: with blanket *.g.cs exclusion, non-generated .g.cs files are masked', () => {
	// An arbitrary .g.cs file that is NOT generated by Kiota — it
	// contains real code and must be counted as production.
	const nonGeneratedGcs = 'apps/api/Modules/Foo/SomeCustom.g.cs';

	const result = isSpecFile(nonGeneratedGcs);

	// BUGGY condition (asserted): the file IS excluded (blanket pattern).
	// On corrected code, isSpecFile returns false (not in GENERATED_FILE_PATHS),
	// so this assertion FAILS — the kept-red state.
	assert.strictEqual(
		result,
		true,
		'RED proof: with blanket *.g.cs exclusion, non-generated .g.cs files are masked',
	);
});
